<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();csrf_check();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$act=$_POST['action']??'';if($act==='delete'){$s=db()->prepare('DELETE FROM student_academics WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Academic record deleted.');log_event('Academic record deleted');header('Location: academics.php');exit;}if($act==='save'){$student=(int)($_POST['student_id']??0);$course=(int)($_POST['course_id']??0);$year=trim((string)($_POST['academic_year']??''));$level=trim((string)($_POST['year_level']??''));$sem=trim((string)($_POST['semester']??''));$enroll=(string)($_POST['enrollment_status']??'Enrolled');$end=(string)($_POST['end_status']??'Ongoing');$remarks=trim((string)($_POST['remarks']??''));if(!$student||!$course||$year===''||$level===''||$sem==='')throw new RuntimeException('Student, course, academic year, year level, and semester are required.');if(!in_array($enroll,['Enrolled','Completed','Withdrawn','Failed'],true)||!in_array($end,['Ongoing','Completed','Withdrawn','Failed'],true))throw new RuntimeException('Invalid academic status.');$v=[$student,$course,$year,$level,$sem,$enroll,$end,$remarks?:null];$id=(int)($_POST['id']??0);if($id){$v[]=$id;$s=db()->prepare('UPDATE student_academics SET student_id=?,course_id=?,academic_year=?,year_level=?,semester=?,enrollment_status=?,end_status=?,remarks=? WHERE id=?');$s->execute($v);}else{$s=db()->prepare('INSERT INTO student_academics(student_id,course_id,academic_year,year_level,semester,enrollment_status,end_status,remarks) VALUES(?,?,?,?,?,?,?,?)');$s->execute($v);}flash('Academic record saved.');log_event('Academic record saved');header('Location: academics.php');exit;}}catch(Throwable $ex){error_log((string)$ex);$error=$ex instanceof RuntimeException?$ex->getMessage():'Could not save academic record. Check student and course selection.';}}
$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM student_academics WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$students=db()->query('SELECT id,student_number,first_name,last_name FROM students ORDER BY last_name')->fetchAll();$courses=db()->query('SELECT id,course_code,course_name FROM courses ORDER BY course_code')->fetchAll();$filter=(int)($_GET['student_id']??0);
$sql='SELECT a.*,s.student_number,s.first_name,s.last_name,c.course_code,c.course_name FROM student_academics a JOIN students s ON s.id=a.student_id JOIN courses c ON c.id=a.course_id';$rows;if($filter){$s=db()->prepare($sql.' WHERE a.student_id=? ORDER BY a.id DESC');$s->execute([$filter]);$rows=$s->fetchAll();}else{$rows=db()->query($sql.' ORDER BY a.id DESC')->fetchAll();}
$page_title='Academic History';require __DIR__.'/includes/header.php';?>
<h1>Student Academic History</h1><section class="panel"><h2><?= $edit?'Edit':'Add' ?> Academic Record</h2><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><?php if(!$students||!$courses):?><p>Add at least one student and one course first.</p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Student</label><select name="student_id" required><?php foreach($students as $s):?><option value="<?=e($s['id'])?>" <?=((int)($edit['student_id']??$filter)===(int)$s['id'])?'selected':''?>><?=e($s['student_number'].' - '.$s['last_name'].', '.$s['first_name'])?></option><?php endforeach;?></select><label>Course</label><select name="course_id" required><?php foreach($courses as $c):?><option value="<?=e($c['id'])?>" <?=((int)($edit['course_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['course_code'].' - '.$c['course_name'])?></option><?php endforeach;?></select><label>Academic Year</label><input name="academic_year" placeholder="2026-2027" required value="<?=e($edit['academic_year']??'')?>"><label>Year Level</label><input name="year_level" placeholder="1st Year" required value="<?=e($edit['year_level']??'')?>"><label>Semester</label><input name="semester" placeholder="1st Semester" required value="<?=e($edit['semester']??'')?>"><label>Enrollment Status</label><select name="enrollment_status"><?php foreach(['Enrolled','Completed','Withdrawn','Failed'] as $v):?><option <?=($edit['enrollment_status']??'Enrolled')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select><label>End Status</label><select name="end_status"><?php foreach(['Ongoing','Completed','Withdrawn','Failed'] as $v):?><option <?=($edit['end_status']??'Ongoing')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select><label>Remarks</label><input name="remarks" value="<?=e($edit['remarks']??'')?>"><button>Save Academic Record</button></form><?php endif;?></section>
<section class="panel"><h2>Academic Records</h2><div style="overflow-x:auto"><table><tr><th>Student</th><th>Course</th><th>Academic Year</th><th>Year</th><th>Semester</th><th>Enrollment</th><th>End Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['student_number'].' '.$r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['course_code'].' '.$r['course_name'])?></td><td><?=e($r['academic_year'])?></td><td><?=e($r['year_level'])?></td><td><?=e($r['semester'])?></td><td><?=e($r['enrollment_status'])?></td><td><?=e($r['end_status'])?></td><td><a href="?edit=<?=e($r['id'])?>">Edit</a> <form class="inline" method="post" onsubmit="return confirm('Delete academic record?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></table></div></section><?php require __DIR__.'/includes/footer.php';?>